<div class="card">
    <div class="card-header">
        <h3>24.&nbsp;maja 2026&nbsp;r.</h3>
        <h3>Uroczystość Zesłania Ducha Świętego</h3>
    </div>
    <div class="col">
        <p>1. Dzisiaj, niedzielą Zesłania Ducha Świętego, kończymy okres
        wielkanocny.</p>
        <p>2. Jutro święto NMP Matki Kościoła, a&nbsp;w&nbsp;czwartek Jezusa
        Chrystusa Najwyższego i&nbsp;Wiecznego Kapłana.</p>
        <p>3. W&nbsp;wtorek Dzień Matki. Zapraszamy do&nbsp;modlitwy
        za&nbsp;nasze Mamy, o&nbsp;wieczny pokój dla zmarłych i&nbsp;Boże
        błogosławieństwo dla żyjących.</p>
        <p>4. W&nbsp;przyszłą niedzielę, niedzielę Trójcy Świętej, kończy się
        okres spowiedzi i&nbsp;komunii wielkanocnej.</p>
        <p>5. W&nbsp;przyszłą niedzielę 31&nbsp;maja, na&nbsp;Mszy Świętej
        o&nbsp;godz.&nbsp;12.30, dzieci z&nbsp;naszej parafii przyjmą pierwszy
        raz komunię świętą.</p>
        <p>6. Próba generalne przed uroczystością pierwszej komunii
        w&nbsp;środę 27&nbsp;maja o&nbsp;godz.&nbsp;18.30.</p>
        <p>7. Spowiedź dla dzieci pierwszokomunijnych i&nbsp;ich rodziców
        w&nbsp;piątek 29&nbsp;maja o&nbsp;godz.&nbsp;16.00.</p>
        <p>8. Spotkanie dla dzieci rocznicowych z&nbsp;klas czwartych
        w&nbsp;sobotę 30&nbsp;maja o&nbsp;godz.&nbsp;9.00.</p>
        <p>9. We&nbsp;wtorek 26&nbsp;maja, na&nbsp;godz.&nbsp;19.00,
        zapraszamy na&nbsp;spotkanie organizacyjne wszystkich udających się
        na&nbsp;pielgrzymkę do&nbsp;Portugalii. Na&nbsp;spotkanie należy
        zabrać dokument tożsamości.</p>
        <p>10. W&nbsp;najbliższą sobotę 30&nbsp;maja odbędzie się
        II&nbsp;diecezjalna pielgrzymka kobiet do&nbsp;Sanktuarium Matki Bożej
        Różańcowej w&nbsp;Ożarowie. Szczegóły na&nbsp;plakacie.</p>
        <p>11. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        naszej parafii. Wszystkim obchodzącym imieniny, rocznice
        i&nbsp;jubileusze składamy serdeczne życzenia. Naszym Parafianom
        i&nbsp;Gościom życzymy błogosławionej niedzieli.</p>
        <p>
            <span style="float: left;">Sandomierz, 24.&nbsp;maja 2026&nbsp;r.</span>
            <span style="float: right; text-align: right;">ks.&nbsp;proboszcz Rafał Kobiałka</span>
