<div class="card">
    <div class="card-header">
        <h3>17.&nbsp;maja 2026&nbsp;r.</h3>
        <h3>Uroczystość Wniebowstąpienia Pańskiego</h3>
    </div>
    <div class="col">
        <p>1. Przed nami ostatni tydzień okresu wielkanocnego. Zapraszamy
        na&nbsp;nowennę przed Uroczystością Zesłania Ducha Świętego,
        codziennie podczas nabożeństwa majowego o&nbsp;godz.&nbsp;17.30.</p>
        <p>2. Spotkanie dla dzieci pierwszokomunijnych w&nbsp;środę
        o&nbsp;godz.&nbsp;18.30 i&nbsp;w&nbsp;sobotę o&nbsp;godz.&nbsp;9.00.</p>
        <p>3. Spotkanie dla dzieci z&nbsp;klas czwartych obchodzących rocznicę
        komunii świętej w&nbsp;sobotę 23&nbsp;maja o&nbsp;godz.&nbsp;10.30.</p>
        <p>4. Zapraszamy młodzież z&nbsp;klas VI i&nbsp;VII przygotowujących
        się do&nbsp;sakramentu bierzmowania w&nbsp;przyszłych latach,
        na&nbsp;ostatnie w&nbsp;tym roku spotkanie formacyjne, w&nbsp;sobotę
        od&nbsp;godz.&nbsp;9.00 do&nbsp;11.00 w&nbsp;salce na&nbsp;plebanii.</p>
        <p>5. W&nbsp;najbliższą sobotę, w&nbsp;Wigilię Zesłania Ducha Świętego,
        zapraszamy na&nbsp;kolejny wieczór uwielbienia. Początek
        o&nbsp;godz.&nbsp;18.00.</p>
        <p>6. W&nbsp;najbliższy wtorek, 19&nbsp;maja, jak w&nbsp;każdy trzeci
        wtorek miesiąca w&nbsp;tym roku, zapraszamy na&nbsp;kolejne spotkanie
        Akademii Biblijnej w&nbsp;Sandomierzu; poprowadzi je&nbsp;wykładowca
        Pisma świętego w&nbsp;naszym seminarium, ks.&nbsp;Paweł Lasek. Tematem
        tego spotkania będzie: List św.&nbsp;Pawła do&nbsp;Rzymian. Spotkanie
        będzie we&nbsp;wtorek, 19&nbsp;maja, o&nbsp;godz.&nbsp;18.45,
        w&nbsp;auli Wyższego Seminarium Duchownego. W&nbsp;spotkaniach będzie
        można uczestniczyć także internetowo, będą ono transmitowane przez
        Facebooka, na&nbsp;profilu <em><a href="https://www.facebook.com/wsdsandomierz/">WSD Sandomierz</a> </em>.
        Serdecznie zapraszamy!</p>
        <p>7. W&nbsp;najbliższą sobotę, 23&nbsp;maja, odbędzie się wydarzenie
        upamiętniające biskupa Franciszka Jopa, kapłana i&nbsp;sufragana
        sandomierskiego. O&nbsp;godz.&nbsp;9.30 konferencja naukowa
        w&nbsp;Diecezjalnym Centrum <em>Quo Vadis</em>. O&nbsp;17.30
        w&nbsp;bazylice katedralnej Msza Święta z&nbsp;okazji 50&nbsp;rocznicy
        śmierci bpa Jopa.</p>
        <p>8. W&nbsp;przyszłą niedzielę, 24&nbsp;maja, o&nbsp;godz.&nbsp;16.30
        w&nbsp;bazylice katedralnej odbędzie się koncert pieśni maryjnych
        w&nbsp;wykonaniu chóru katedralnego.</p>
        <p>9. W&nbsp;ostatnim czasie swoją ziemską pielgrzymkę zakończył nasz
        parafianin Henryk Piętowski. Polećmy go&nbsp;Bożemu miłosierdziu.</p>
        <p>10. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        naszej parafii. Wszystkim obchodzącym imieniny, rocznice
        i&nbsp;jubileusze składamy serdeczne życzenia. Naszym parafianom
        i&nbsp;gościom życzymy błogosławionej niedzieli.</p>
        <p>
            <span style="float: left;">Sandomierz, 17.&nbsp;maja 2026&nbsp;r.</span>
            <span style="float: right; text-align: right;">ks.&nbsp;proboszcz Rafał Kobiałka</span>
        </p>
    </div>
</div>
