<div class="card">
    <div class="card-header">
        <h3>10.&nbsp;maja 2026&nbsp;r.</h3>
        <h3>VI&nbsp;Niedziela Wielkanocna</h3>
    </div>
    <div class="col">
        <p>1. W&nbsp;tym tygodniu oddajemy cześć świętym: w&nbsp;środę Matce
        Bożej z&nbsp;Fatimy, w&nbsp;czwartek świętemu Maciejowi apostołowi,
        w&nbsp;sobotę świętem Andrzejowi Boboli, kapłanowi i&nbsp;męczennikowi,
        patronowi Polski.</p>
        <p>2. 13&nbsp;maja wypada 45&nbsp;rocznica nieudanego zamachu
        na&nbsp;papieża Jana Pawła&nbsp;II. Z&nbsp;tej okazji kino Wisła
        w&nbsp;Tarnobrzegu zaprasza na&nbsp;film Maryja Matka Papieża.
        Szczegóły na&nbsp;plakacie.</p>
        <p>3. W&nbsp;przyszłą niedzielę obchodzić będziemy Uroczystość
        Wniebowstąpienia Pańskiego.</p>
        <p>4. Nabożeństwa majowe każdego dnia o&nbsp;godz.&nbsp;17.30.
        Od&nbsp;piątku podczas nabożeństw będziemy także prosić
        w&nbsp;ramach nowenny przed Zesłaniem Ducha Świętego o&nbsp;Jego dary.
        Serdecznie zapraszamy.</p>
        <p>5. W&nbsp;środę, 13&nbsp;maja, zapraszamy na&nbsp;spotkanie dzieci
        pierwszokomunijne. Początek po&nbsp;godz.&nbsp;18.30.</p>
        <p>6. W&nbsp;tym tygodniu swoją ziemską pielgrzymkę zakończyli nasi
        parafianie: Alicja Bieżanek oraz Jan Jakuła. Polećmy ich Bożemu
        miłosierdziu.</p>
        <p>7.  Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        parafii. Wszystkim obchodzącym imieniny, rocznice i&nbsp;jubileusze
        składamy serdeczne życzenia. Wszystkim Parafianom i&nbsp;Gościom
        życzymy błogosławionej niedzieli.</p>
