<div class="card">
    <div class="card-header">
        <h3>19.&nbsp;kwietnia 2026&nbsp;r.</h3>
        <h3>III&nbsp;niedziela wielkanocna</h3>
    </div>
    <div class="col">
        <p>1. W&nbsp;najbliższy wtorek, 21&nbsp;kwietnia, na&nbsp;Mszy Świętej
        o&nbsp;godz.&nbsp;18.00, ksiądz biskup Krzysztof Nitkiewicz udzieli
        sakramentu bierzmowania. Przyjmującym ten sakrament z&nbsp;całego
        serca życzymy, aby był on&nbsp;rzeczywiście sakramentem wzmacniającym
        odważne wyznawanie wiary w&nbsp;świecie.</p>
        <p>2. Spowiedź dla kandydatów do&nbsp;bierzmowania w&nbsp;poniedziałek
        od&nbsp;godz.&nbsp;17.15.</p>
        <p>3. Próba liturgiczna przed przyjęciem sakramentu bierzmowania także
        w&nbsp;poniedziałek o&nbsp;godz.&nbsp;18.30.</p>
        <p>4. W&nbsp;czwartek, 23&nbsp;kwietnia, przypada Uroczystość Świętego
        Wojciecha, głównego patrona Polski. Pamiętajmy w&nbsp;modlitwie
        o&nbsp;naszej Ojczyźnie. Jest to&nbsp;także dzień imienin księdza
        Wojciecha, naszego Wikariusza. Będziemy modlić się za&nbsp;Niego
        na&nbsp;Mszach Świętych o&nbsp;godz.&nbsp;6.30 i&nbsp;18.00.</p>
        <p>5. W&nbsp;najbliższy wtorek zapraszamy na&nbsp;kolejne spotkanie
        Akademii Biblijnej w&nbsp;Sandomierzu; poprowadzi je&nbsp;wykładowca
        Pisma świętego w&nbsp;naszym seminarium, ks.&nbsp;Paweł Lasek. Tematem
        tego spotkania będzie: Drugi List św.&nbsp;Pawła do&nbsp;Koryntian.
        Początek o&nbsp;godz.&nbsp;19.00, w&nbsp;auli Wyższego Seminarium
        Duchownego. W&nbsp;spotkaniu będzie można uczestniczyć także
        internetowo, będzie ono transmitowane przez Facebooka, na&nbsp;profilu
        <a href="https://www.facebook.com/wsdsandomierz/">WSDSandomierz</a>.</p>
        <p>6. W&nbsp;najbliższą sobotę, 25&nbsp;kwietnia, zapraszamy
        na&nbsp;kolejny wieczór uwielbienia. Rozpoczęcie
        o&nbsp;godz.&nbsp;18.00.</p>
        <p>7. W&nbsp;przyszłą niedzielę 26&nbsp;kwietnia, wspólnota
        seminaryjna zaprasza na&nbsp;nabożeństwo Drogi Światła w&nbsp;ogrodach
        seminaryjnych. Początek o&nbsp;godz.&nbsp;19.00. Organizatorzy
        zachęcają, aby zabrać ze&nbsp;sobą świece lub lampiony.</p>
        <p>8. W&nbsp;związku z&nbsp;bierzmowaniem kancelaria parafialna będzie
        nieczynna we&nbsp;wtorek. Zapraszamy w&nbsp;poniedziałek
        i&nbsp;czwartek po&nbsp;Mszy wieczornej. W&nbsp;piątek wyjątkowo
        kancelaria czynna będzie od&nbsp;17.00 do&nbsp;17.30.</p>
        <p>9. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        parafii. Wszystkim obchodzącym imieniny, rocznice i&nbsp;jubileusze
        składamy serdeczne życzenia. Wszystkim Parafianom i&nbsp;Gościom
        życzymy błogosławionej niedzieli.</p>
        <p>
            <span style="float: left;">Sandomierz, 19.&nbsp;kwietnia 2026&nbsp;r.</span>
            <span style="float: right; text-align: right;">ks.&nbsp;proboszcz Rafał Kobiałka</span>
        </p>
