<div class="card">
    <div class="card-header">
        <h3>8.&nbsp;marca 2026&nbsp;r.</h3>
        <h3>III&nbsp;niedziela Wielkiego Postu, Rok&nbsp;A</h3>
    </div>
    <div class="col">
        <p>1. Przeżywamy okres Wielkiego Postu. Zachęcamy do&nbsp;udziału
        w&nbsp;nabożeństwach pasyjnych.</p>
        <ul>
        <li>Droga krzyżowa w&nbsp;piątek o&nbsp;godz.&nbsp;16.00 dla dzieci,
        o&nbsp;godz.&nbsp;17.15 dla dorosłych;</li>
        <li>Gorzkie żale w&nbsp;niedzielę o&nbsp;godz.&nbsp;17.15.</li>
        </ul>
        <p>2. W&nbsp;dni powszednie Wielkiego Postu trwa całodzienna adoracja
        Pana Jezusa w&nbsp;Najświętszym Sakramencie. Bardzo cieszy nas,
        że&nbsp;Pan Jezus jest praktycznie cały czas adorowany. Bardzo
        zachęcamy w&nbsp;dalszym ciągu do&nbsp;wpisywania się
        na&nbsp;konkretne godziny adoracji.</p>
        <p>3. We&nbsp;<strong>wtorek 10&nbsp;marca</strong> rozpoczyna się
        nowenna przed uroczystością św.&nbsp;Józefa. W&nbsp;naszym kościele
        przyzywać będziemy Jego opieki modląc się Litanią na&nbsp;zakończenie
        adoracji o&nbsp;godz.&nbsp;17.50.</p>
        <p>4. W&nbsp;najbliższy <strong>piątek 13&nbsp;marca</strong>
        zapraszam serdecznie rodziców dzieci pierwszokomunijnych z&nbsp;roku
        2026 na&nbsp;katechezę na&nbsp;temat sakramentu pokuty. Początek
        po&nbsp;Mszy Świętej wieczornej.</p>
        <p>5. W&nbsp;<strong>sobotę 21&nbsp;marca</strong> w&nbsp;parafii
        pw.&nbsp;św.&nbsp;Floriana w&nbsp;Stalowej Woli odbędzie się Dzień
        Skupienia dla osób będących w&nbsp;żałobie. Początek
        o&nbsp;godz.&nbsp;9.00. Szczegóły na&nbsp;plakacie.</p>
        <p>6. Również <strong>21 marca</strong> w&nbsp;Wyższym Seminarium
        Duchownym odbędzie się „Dzień Pustyni dla Sandomierza”. Będzie
        to&nbsp;jednodniowe zasłuchanie w&nbsp;Słowo Boże metodą
        <em>lectio divina</em> dla tych, którzy potrzebują ciszy
        i&nbsp;modlitwy, nie tylko dla mieszkańców Sandomierza.</p>
        <p>7. Sandomierski sztab EDK zaprasza na&nbsp;kolejną edycję
        Ekstremalnej Drogi Krzyżowej. Rozpoczęcie w&nbsp;<strong>piątek
        27&nbsp;marca</strong> Mszą Świętą o&nbsp;godzinie 20.00
        w&nbsp;kościele Ducha Świętego. Zapisy przez stronę internetową
        <a href="https://edk.org.pl">https://edk.org.pl</a> lub bezpośrednio
        przed EDK 27&nbsp;marca od&nbsp;godz.&nbsp;19.00.</p>
        <p>8. W&nbsp;związku z&nbsp;pojawiającymi się licznymi pytaniami
        i&nbsp;prośbami chcielibyśmy poinformować, że&nbsp;w&nbsp;roku 2027
        będą dwa terminy pierwszej komunii świętej: w&nbsp;czwartą
        i&nbsp;piątą niedzielę maja. Natomiast w&nbsp;kolejnych latach
        (od&nbsp;roku 2028) uroczystość pierwszej komunii będzie odbywać się
        w&nbsp;czwartą niedzielę maja.</p>
        <p>9. W&nbsp;zeszłym tygodniu złożyliście do&nbsp;puszek
        4531,50&nbsp;zł. na&nbsp;cele misyjne. Dziękuję za&nbsp;Waszą
        ofiarność!</p>
        <p>10. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        naszej parafii. Wszystkim obchodzącym imieniny, rocznice
        i&nbsp;jubileusze składamy serdeczne życzenia. Naszym Parafianom
        i&nbsp;Gościom życzymy błogosławionej niedzieli.</p>
