        <p>2. W&nbsp;tym tygodniu wypada pierwszy czwartek, piątek
        i&nbsp;sobota miesiąca.</p>
        <p>3. Spowiedź w&nbsp;piątek od&nbsp;godz.&nbsp;15.30 do&nbsp;16.00
        (na&nbsp;tę&nbsp;godzinę zapraszamy dzieci przed drogą krzyżową) oraz
