        <p>4. Odwiedziny chorych w&nbsp;domach w&nbsp;piątek
        od&nbsp;godz.&nbsp;8.00.</p>
        <p>5. W&nbsp;sobotę różaniec wynagradzający o&nbsp;godz.&nbsp;17.30.</p>
        <p>6. W&nbsp;środę 4&nbsp;marca, po&nbsp;Mszy Świętej wieczornej,
        około godz.&nbsp;18.40 zbiórka ministrantów w&nbsp;kościele.</p>
        <p>7. W&nbsp;najbliższy piątek 6&nbsp;marca, obowiązkowe spotkanie dla
        przyjmujących w&nbsp;tym roku sakrament bierzmowania.
        Na&nbsp;to&nbsp;spotkanie zapraszamy również rodziców. Rozpoczęcie
        spotkania Mszą Świętą o&nbsp;godz.&nbsp;18.00,
        a&nbsp;po&nbsp;Mszy&nbsp;Św. zebranie w&nbsp;kościele.</p>
        <p>8. W&nbsp;sobotę 7&nbsp;marca spotkanie dla dzieci
        pierwszokomunijnych. Wyjątkowo spotkanie rozpocznie się
        o&nbsp;godz.&nbsp;8.00. Prosimy o&nbsp;punktualność.</p>
        <p>9. Parafia św.&nbsp;Józefa w&nbsp;Sandomierzu i&nbsp;Wojownicy
        Maryi Sandomierz zapraszają serdecznie na&nbsp;spotkanie
        z&nbsp;ks.&nbsp;Łukaszem Platą pt. „O&nbsp;Miłości, która
        na&nbsp;śmierć nie umiera” w&nbsp;najbliższa sobotę 7&nbsp;marca
        o&nbsp;godz.&nbsp;18.00, w&nbsp;kościele pw.&nbsp;Św.&nbsp;Józefa
        w&nbsp;Sandomierzu. Szczegóły na&nbsp;plakacie w&nbsp;gablocie.</p>
        <p>10. W&nbsp;sobotę 14&nbsp;marca odbędzie się w&nbsp;naszej parafii
        wielkopostny dzień skupienia dla związków niesakramentalnych. Zapisy
        i&nbsp;informacje u&nbsp;księdza Krystiana.</p>
        <p>11. Po&nbsp;Mszy Świętej można złożyć ofiarę na&nbsp;misje
        do&nbsp;puszek wystawionych na&nbsp;stoliku pod chórem.</p>
        <p>12. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        naszej parafii. Wszystkim obchodzącym imieniny, rocznice
        i&nbsp;jubileusze składamy serdeczne życzenia. Naszym parafianom
        i&nbsp;gościom życzymy błogosławionej niedzieli.</p>
        <p>
            <span style="float: left;">Sandomierz, 1.&nbsp;marca 2026&nbsp;r.</span>
            <span style="float: right; text-align: right;">ks.&nbsp;proboszcz Rafał Kobiałka</span>
