<div class="card">
    <div class="card-header">
        <h3>22.&nbsp;lutego 2026&nbsp;r.</h3>
        <h3>I&nbsp;niedziela Wielkiego Postu, Rok&nbsp;A</h3>
    </div>
    <div class="col">
        <p>1. W&nbsp;środę popielcową rozpoczęliśmy Wielki Post. Bardzo
        dziękuję ojcu Michałowi za&nbsp;wygłoszenie rekolekcji
        i&nbsp;wprowadzenie nas w&nbsp;ten czas przygotowania do&nbsp;Świąt
        Paschalnych.</p>
        <p>2. W&nbsp;Wielkim Poście zapraszamy na&nbsp;nabożeństwa pasyjne:</p>
        <p>    a.&nbsp;Droga Krzyżowa w <strong>piątki o&nbsp;16.00 dla dzieci
        i&nbsp;o&nbsp;17.15 dla dorosłych</strong>,</p>
        <p>    b.&nbsp;Gorzkie żale w&nbsp;<strong>niedziele
        o&nbsp;17.15</strong>.</p>
        <p>3. W&nbsp;dni powszednie Wielkiego Postu Pan Jezus
        w&nbsp;Najświętszym Sakramencie jest wystawiony do&nbsp;adoracji
        w&nbsp;bocznej kaplicy naszego kościoła. Bardzo dziękuję za&nbsp;to,
        że&nbsp;przychodzicie na&nbsp;modlitwę. I&nbsp;bardzo zachęcam
        do&nbsp;tego, żeby wpisywać się na&nbsp;konkretne godziny adoracji.</p>
        <p>4. W&nbsp;najbliższy <strong>wtorek 24 lutego</strong> odbędzie
        się pierwsze spotkanie Seminarium Odnowy Wiary.
        To&nbsp;dziesięciotygodniowy cykl spotkań dotyczących fundamentów
        wiary. Zapraszamy każdego, kto chciałby przyjrzeć się swojej
        chrześcijańskiej wierze, kto chciałby ją&nbsp;pogłębić, a&nbsp;może
        odpowiedzieć sobie na&nbsp;pytanie w&nbsp;co&nbsp;tak naprawdę
        wierzymy jako katolicy. Spotkanie pierwsze w&nbsp;najbliższy wtorek
        po&nbsp;Mszy świętej o&nbsp;godz.&nbsp;18.00 w&nbsp;salce
        na&nbsp;plebanii. Kolejne spotkania będą miały miejsce w&nbsp;środy
        po&nbsp;Mszy świętej wieczornej, a&nbsp;więc około godziny 18.40.</p>
        <p>5. W&nbsp;najbliższą <strong>sobotę 28&nbsp;lutego</strong>
        zapraszamy na&nbsp;kolejny Wieczór Uwielbienia. Początek
        o&nbsp;godzinie 18.00.</p>
        <p>6. W&nbsp;przyszłą <strong>niedzielę 1&nbsp;marca</strong>,
        po&nbsp;Mszy świętej o&nbsp;godzinie 12.30 zapraszam na&nbsp;krótkie
        spotkanie rodziców dzieci pierwszokomunijnych z&nbsp;roku 2027.</p>
        <p>7. Dziękuję bardzo za&nbsp;Waszą ofiarność. Na&nbsp;pomoc ofiarom
        wojny na&nbsp;Ukrainie złożyliście do&nbsp;puszek 2847&nbsp;zł.
        Pieniądze zostały przekazane Caritas Archidiecezji Lwowskiej.
        Natomiast na&nbsp;tacę w&nbsp;środę popielcową złożyliście
        5056&nbsp;zł. Kwota została przekazana naszej diecezjalnej Caritas.</p>
        <p>8. Dziękuję także za&nbsp;cotygodniową ofiarność, jaką wykazujecie
        składając ofiary na&nbsp;tacę. Pomaga nam to&nbsp;w&nbsp;spokojnym
        bieżącym utrzymaniu parafii.</p>
        <p>9. Jeśli ktoś szuka pomysłu na&nbsp;jałmużnę wielkopostną,
        to&nbsp;może podzielić się swoimi dobrami z&nbsp;misjonarzami.
        W&nbsp;przyszłą niedzielę będzie można złożyć ofiarę na&nbsp;misje
        do&nbsp;puszek. Na&nbsp;plakacie jest także informacja o&nbsp;zbiórce
        na&nbsp;działalność misyjną księdza Grzegorza Kasprzyckiego,
        misjonarza z&nbsp;naszej diecezji pracującego w&nbsp;Papui Nowej
        Gwinei.</p>
        <p>10. Księża Pallotyni organizują pielgrzymkę do&nbsp;Wilna.
        Szczegóły na&nbsp;plakacie w&nbsp;gablocie.</p>
        <p>11. W&nbsp;minionym tygodniu swoją ziemską pielgrzymkę zakończyła
        Marianna Chmiel. Polećmy Ją&nbsp;Bożemu miłosierdziu.</p>
        <p>12. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        naszej parafii! Wszystkim obchodzącym imieniny, rocznice
        i&nbsp;jubileusze składamy serdeczne życzenia. Wszystkim Parafianom
        i&nbsp;Gościom życzymy błogosławionej niedzieli.</p>
        <p>
            <span style="float: left;">Sandomierz, 22.&nbsp;lutego 2026&nbsp;r.</span>
            <span style="float: right; text-align: right;">ks.&nbsp;proboszcz Rafał Kobiałka</span>
        </p>
    </div>
</div>
