<div class="card">
    <div class="card-header">
        <h3>25.&nbsp;stycznia 2026&nbsp;r.</h3>
        <h3>III&nbsp;niedziela zwykła, Rok&nbsp;A</h3>
    </div>
    <div class="col">
        <p>1. Zakończyliśmy wizytę duszpasterską. Bardzo dziękujemy
        za&nbsp;otwarte drzwi, życzliwość, ofiary. Cieszy nas, że&nbsp;wielu
        z&nbsp;Was naprawdę szczerze i&nbsp;z&nbsp;radością nas oczekuje!
        Serdeczne <em>Bóg zapłać</em> za&nbsp;wszystko!</p>
        <p>2. Dziękuję także ministrantom za&nbsp;pomoc i&nbsp;księdzu
        Wojciechowi za&nbsp;pomysł i&nbsp;czuwanie nad grafikiem.
        W&nbsp;większość dni ministranci nam towarzyszyli, co&nbsp;bardzo
        usprawniało przebieg wizyty. Dziękuję także i&nbsp;Wam
        za&nbsp;otwartość i&nbsp;wdzięczność wobec ministrantów okazywaną
        w&nbsp;najróżniejszy sposób.</p>
        <p>3. W&nbsp;tym tygodniu oddajemy cześć świętym: w&nbsp;poniedziałek
        Tymoteuszowi i&nbsp;Tytusowi, we&nbsp;wtorek błogosławionemu Jerzemu
        Matulewiczowi, w&nbsp;środę Tomaszowi z&nbsp;Akwinu
        i&nbsp;w&nbsp;sobotę Janowi Bosko.</p>
        <p>4. W&nbsp;najbliższą <strong>sobotę 31&nbsp;stycznia</strong>
        będzie miał miejsce kolejny wieczór uwielbienia. Początek
        o&nbsp;godz.&nbsp;18.00. Serdecznie zapraszamy.</p>
        <p>5. Księża Zmartwychwstańcy zapraszają do&nbsp;Sulisławic&nbsp;7
        i&nbsp;8&nbsp;lutego na&nbsp;pielgrzymkę sadowników
        i&nbsp;ogrodników.</p>
        <p>6. W&nbsp;ostatnim tygodniu swoją ziemską pielgrzymkę zakończyli
        nasi parafianie: Genowefa Zimnicka oraz Gustaw Kanios. Polećmy Ich
        Bożemu miłosierdziu.</p>
        <p>7. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        naszej parafii. Wszystkim obchodzącym imieniny, rocznice
        i&nbsp;jubileusze składamy serdeczne życzenia. Naszym Parafianom
        i&nbsp;Gościom życzymy błogosławionej niedzieli!</p>
