<div class="card">
    <div class="card-header">
        <h3>11.&nbsp;stycznia 2026&nbsp;r.</h3>
        <h3>Niedziela Chrztu Pańskiego, Rok&nbsp;A</h3>
    </div>
    <div class="col">
        <p>1. Dziękujemy za&nbsp;życzliwą atmosferę oraz za&nbsp;otwartość
        na&nbsp;nas księży i&nbsp;naszych ministrantów podczas wizyty
        duszpasterskiej. Plan na&nbsp;najbliższe dni wywieszony jest
        w&nbsp;gablocie i&nbsp;podany na&nbsp;stronie internetowej. Prosimy
        o&nbsp;kontakt, jeśli gdzieś przez przeoczenie nie dotarliśmy,
        a&nbsp;ktoś na&nbsp;nas oczekiwał i&nbsp;chciałby nas przyjąć.</p>
        <p>2. 18&nbsp;stycznia o&nbsp;godz.&nbsp;19:00 w&nbsp;kościele
        św.&nbsp;Józefa odbędzie się koncert kolęd Violi Brzezińskiej.</p>
        <p>3. W&nbsp;dniach 14-15&nbsp;lutego w&nbsp;Stalowej Woli odbędzie
        się Walentynkowy Dzień Małżeński. W&nbsp;planie między innymi
        konferencja pt.&nbsp;<em>Jak twórczo rozwiązywać konflikty
        małżeńskie</em> oraz zabawa walentynkowa. Szczegóły na&nbsp;plakacie
        oraz u&nbsp;księdza Krystiana.</p>
        <p>4. Dziękuję bardzo za&nbsp;Waszą ofiarność. Na&nbsp;duszpasterstwo
        młodzieży z&nbsp;ofiar składanych w&nbsp;Uroczystość Objawienia
        Pańskiego zebraliśmy 3433,72&nbsp;zł.</p>
        <p>5. Natomiast na&nbsp;tacę misyjną, także w&nbsp;Uroczystość
        Objawienia Pańskiego złożyliście 6853,60&nbsp;zł. <em>Bóg
        zapłać!</em></p>
        <p>6. Dziękujemy za&nbsp;wszelkie duchowe i&nbsp;materialne wsparcie
        naszej parafii. Za&nbsp;ofiary składane podczas kolędy, jak
        i&nbsp;te&nbsp;wpłacane na&nbsp;konto. Wszystkim obchodzącym
        imieniny, rocznice i&nbsp;jubileusze składamy serdeczne życzenia.
        Naszym parafianom i&nbsp;gościom życzymy błogosławionej niedzieli.</p>
        <p>
            <span style="float: left;">Sandomierz, 11.&nbsp;stycznia 2026&nbsp;r.</span>
            <span style="float: right; text-align: right;">ks.&nbsp;proboszcz Rafał Kobiałka</span>
        </p>
    </div>
</div>
